import{_ as d,o as e,c as r,a4 as o}from"./chunks/framework.BMj-uaUw.js";const b=JSON.parse('{"title":"管理端需求规格","description":"","frontmatter":{},"headers":[{"level":2,"title":"一、项目目标","slug":"一、项目目标","link":"#一、项目目标","children":[]},{"level":2,"title":"二、功能清单","slug":"二、功能清单","link":"#二、功能清单","children":[{"level":3,"title":"模块一：登录鉴权","slug":"模块一-登录鉴权","link":"#模块一-登录鉴权","children":[]},{"level":3,"title":"模块二：活动管理","slug":"模块二-活动管理","link":"#模块二-活动管理","children":[]},{"level":3,"title":"模块三：报名审核","slug":"模块三-报名审核","link":"#模块三-报名审核","children":[]},{"level":3,"title":"模块四：场地与场次","slug":"模块四-场地与场次","link":"#模块四-场地与场次","children":[]},{"level":3,"title":"模块五：数据看板","slug":"模块五-数据看板","link":"#模块五-数据看板","children":[]}]},{"level":2,"title":"三、页面清单","slug":"三、页面清单","link":"#三、页面清单","children":[]},{"level":2,"title":"四、数据字段","slug":"四、数据字段","link":"#四、数据字段","children":[{"level":3,"title":"活动（Activity）","slug":"活动-activity","link":"#活动-activity","children":[]},{"level":3,"title":"报名记录（Signup）","slug":"报名记录-signup","link":"#报名记录-signup","children":[]},{"level":3,"title":"场地（Venue）","slug":"场地-venue","link":"#场地-venue","children":[]},{"level":3,"title":"场次（Session）","slug":"场次-session","link":"#场次-session","children":[]},{"level":3,"title":"用户（User）","slug":"用户-user","link":"#用户-user","children":[]}]},{"level":2,"title":"五、界面要求","slug":"五、界面要求","link":"#五、界面要求","children":[{"level":3,"title":"活动列表","slug":"活动列表","link":"#活动列表","children":[]},{"level":3,"title":"报名列表","slug":"报名列表","link":"#报名列表","children":[]},{"level":3,"title":"状态与提示文案","slug":"状态与提示文案","link":"#状态与提示文案","children":[]},{"level":3,"title":"空状态与错误状态","slug":"空状态与错误状态","link":"#空状态与错误状态","children":[]}]},{"level":2,"title":"六、非功能要求","slug":"六、非功能要求","link":"#六、非功能要求","children":[{"level":3,"title":"性能","slug":"性能","link":"#性能","children":[]},{"level":3,"title":"兼容性","slug":"兼容性","link":"#兼容性","children":[]},{"level":3,"title":"可用性","slug":"可用性","link":"#可用性","children":[]},{"level":3,"title":"安全","slug":"安全","link":"#安全","children":[]}]},{"level":2,"title":"七、验收方式","slug":"七、验收方式","link":"#七、验收方式","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"project/requirements.md","filePath":"project/requirements.md","lastUpdated":1789500889000}'),a={name:"project/requirements.md"};function n(i,t,l,h,c,s){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="管理端需求规格" tabindex="-1">管理端需求规格 <a class="header-anchor" href="#管理端需求规格" aria-label="Permalink to &quot;管理端需求规格&quot;">​</a></h1><p>这一页把管理端要做的东西写清楚：<strong>有哪些功能、每个功能包含什么字段、界面大概长什么样。</strong></p><p>它不涉及技术实现。技术方案见<a href="/frontend-engineering-course/project/api.html">接口约定</a>和<a href="/frontend-engineering-course/project/structure.html">目录结构</a>。 用户端（学生手机端）的规格不在这里，单独写在<a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a>。</p><h2 id="一、项目目标" tabindex="-1">一、项目目标 <a class="header-anchor" href="#一、项目目标" aria-label="Permalink to &quot;一、项目目标&quot;">​</a></h2><p><strong>一句话</strong>：让校园里的活动从“发通知、收名单、手工统计”变成“线上发布、在线报名、系统审核”。</p><p><strong>要解决的问题</strong>（真实存在的三个痛点）：</p><table tabindex="0"><thead><tr><th>痛点</th><th>现在怎么做的</th><th>做完之后</th></tr></thead><tbody><tr><td>报名靠人工统计</td><td>群里发通知，学生接龙，组织者手工数</td><td>学生在线上报名，系统自动计数</td></tr><tr><td>名额管不住</td><td>报满了还在报名，只能靠组织者喊停</td><td>名额满了报名入口自动关闭</td></tr><tr><td>场地会撞车</td><td>两个活动约了同一个场地同一个时间</td><td>系统检测时段冲突，提交时就拦下</td></tr></tbody></table><p><strong>项目的边界（明确不做的）</strong>：</p><ul><li>管理端不做学生端页面（学生端是独立的一栏，见<a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a>）</li><li>不做消息通知（短信、微信推送）</li><li>不做活动签到</li><li>不做多校区、多学校支持</li></ul><p><strong>把“不做什么”写清楚，比写“做什么”更重要。</strong> 它决定了你遇到新需求时该不该动手。</p><h2 id="二、功能清单" tabindex="-1">二、功能清单 <a class="header-anchor" href="#二、功能清单" aria-label="Permalink to &quot;二、功能清单&quot;">​</a></h2><p>按模块列出所有功能。<strong>每一项都要有明确的验收标准</strong>，否则“做完了”和“没做完”只能靠感觉判断。</p><h3 id="模块一-登录鉴权" tabindex="-1">模块一：登录鉴权 <a class="header-anchor" href="#模块一-登录鉴权" aria-label="Permalink to &quot;模块一：登录鉴权&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>功能</th><th>验收标准</th></tr></thead><tbody><tr><td>A1</td><td>账号密码登录</td><td>输入正确的账号密码能进入后台；错误的给出明确提示</td></tr><tr><td>A2</td><td>登录态保持</td><td>登录后刷新页面仍停留在原页面，不需要重新登录</td></tr><tr><td>A3</td><td>token 失效处理</td><td>token 过期后请求会被拦下并跳回登录页，不会一直转圈</td></tr><tr><td>A4</td><td>路由拦截</td><td>未登录直接访问后台地址会被跳转到登录页，登录后回到原地址</td></tr><tr><td>A5</td><td>角色区分</td><td>组织者和审核员看到不同的菜单和按钮</td></tr><tr><td>A6</td><td>退出登录</td><td>点退出后清理登录态并回到登录页；再访问后台会被拦</td></tr></tbody></table><h3 id="模块二-活动管理" tabindex="-1">模块二：活动管理 <a class="header-anchor" href="#模块二-活动管理" aria-label="Permalink to &quot;模块二：活动管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>功能</th><th>验收标准</th></tr></thead><tbody><tr><td>B1</td><td>活动列表</td><td>支持按标题关键字、状态查询；支持分页；四种状态（加载中 / 有数据 / 无数据 / 失败）都能正确显示</td></tr><tr><td>B2</td><td>新增活动</td><td>填写标题、类型、名额、报名截止时间、活动说明；保存后出现在列表里</td></tr><tr><td>B3</td><td>编辑活动</td><td>字段回填正确；保存后列表和详情同步更新</td></tr><tr><td>B4</td><td>发布活动</td><td>草稿状态的活动发布后变成报名中；报名截止时间已过的不能发布</td></tr><tr><td>B5</td><td>下架 / 恢复</td><td>下架后列表显示已下架标记；恢复后标记消失；草稿和已结束的不能下架</td></tr><tr><td>B6</td><td>删除活动</td><td>只有草稿能删除；删除有二次确认</td></tr><tr><td>B7</td><td>活动详情</td><td>显示完整信息、报名统计（已通过 / 待审核 / 已驳回）、场次数量</td></tr><tr><td>B8</td><td>状态标签</td><td>四种状态有不同颜色的标签，一眼能区分</td></tr></tbody></table><h3 id="模块三-报名审核" tabindex="-1">模块三：报名审核 <a class="header-anchor" href="#模块三-报名审核" aria-label="Permalink to &quot;模块三：报名审核&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>功能</th><th>验收标准</th></tr></thead><tbody><tr><td>C1</td><td>报名列表</td><td>支持按活动、按审核状态、按学生姓名或学号查询；支持分页</td></tr><tr><td>C2</td><td>单活动报名视图</td><td>从活动详情能跳到该活动的报名列表，且已按该活动筛选</td></tr><tr><td>C3</td><td>审核通过</td><td>二次确认后状态变为已通过；活动名额减一</td></tr><tr><td>C4</td><td>审核驳回</td><td>必须填写驳回理由（5 到 100 字）；状态变为已驳回</td></tr><tr><td>C5</td><td>撤销审核</td><td>已通过的撤销后释放名额，报名入口恢复可用</td></tr><tr><td>C6</td><td>名额提示</td><td>名额已满时通过操作被拦下并提示；列表里显示出“42 / 100”这样的进度</td></tr><tr><td>C7</td><td>关联信息</td><td>列表里直接显示活动标题和学生姓名，不用点进详情</td></tr></tbody></table><h3 id="模块四-场地与场次" tabindex="-1">模块四：场地与场次 <a class="header-anchor" href="#模块四-场地与场次" aria-label="Permalink to &quot;模块四：场地与场次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>功能</th><th>验收标准</th></tr></thead><tbody><tr><td>D1</td><td>场地列表</td><td>显示名称、容量、位置、启用状态</td></tr><tr><td>D2</td><td>新增 / 编辑场地</td><td>名称必填且唯一；容量必须是正整数</td></tr><tr><td>D3</td><td>启用 / 停用场地</td><td>停用的场地不出现在新增场次的选项里</td></tr><tr><td>D4</td><td>场次列表</td><td>支持按活动、按日期范围查询</td></tr><tr><td>D5</td><td>新增 / 编辑场次</td><td>选择活动、场地、开始与结束时间；结束后必须晚于开始</td></tr><tr><td>D6</td><td>冲突检测</td><td>同一场地同一时段重叠时提示冲突，并说明和哪个场次的哪段时间冲突；边界相接不算冲突</td></tr><tr><td>D7</td><td>取消场次</td><td>取消后该时段被释放，可以安排新的场次</td></tr></tbody></table><h3 id="模块五-数据看板" tabindex="-1">模块五：数据看板 <a class="header-anchor" href="#模块五-数据看板" aria-label="Permalink to &quot;模块五：数据看板&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>功能</th><th>验收标准</th></tr></thead><tbody><tr><td>E1</td><td>数量指标</td><td>活动总数（按状态分布）、报名总数、待审核数、已通过数</td></tr><tr><td>E2</td><td>名额使用率</td><td>显示整体名额使用率，含算法说明</td></tr><tr><td>E3</td><td>近期活动</td><td>显示最近更新的几条活动，点击能进详情</td></tr><tr><td>E4</td><td>待办提醒</td><td>显示待审核报名数、48 小时内截止报名的活动</td></tr><tr><td>E5</td><td>权限差异</td><td>组织者只统计自己的活动，审核员统计全部</td></tr></tbody></table><h2 id="三、页面清单" tabindex="-1">三、页面清单 <a class="header-anchor" href="#三、页面清单" aria-label="Permalink to &quot;三、页面清单&quot;">​</a></h2><p>“一个页面一个职责”的拆分结果：</p><table tabindex="0"><thead><tr><th>页面</th><th>路由</th><th>模块</th><th>可访问角色</th></tr></thead><tbody><tr><td>登录</td><td><code>/login</code></td><td>登录鉴权</td><td>未登录</td></tr><tr><td>无权限</td><td><code>/403</code></td><td>登录鉴权</td><td>全部</td></tr><tr><td>页面不存在</td><td><code>/404</code></td><td>登录鉴权</td><td>全部</td></tr><tr><td>数据看板</td><td><code>/dashboard</code></td><td>数据看板</td><td>组织者、审核员</td></tr><tr><td>活动列表</td><td><code>/activity</code></td><td>活动管理</td><td>组织者、审核员</td></tr><tr><td>活动详情</td><td><code>/activity/:id</code></td><td>活动管理</td><td>组织者、审核员</td></tr><tr><td>新增活动</td><td><code>/activity/create</code></td><td>活动管理</td><td>组织者</td></tr><tr><td>编辑活动</td><td><code>/activity/:id/edit</code></td><td>活动管理</td><td>组织者</td></tr><tr><td>报名列表</td><td><code>/signup</code></td><td>报名审核</td><td>组织者、审核员</td></tr><tr><td>某活动的报名</td><td><code>/activity/:id/signups</code></td><td>报名审核</td><td>组织者、审核员</td></tr><tr><td>场地列表</td><td><code>/venue</code></td><td>场地与场次</td><td>审核员</td></tr><tr><td>场次列表</td><td><code>/session</code></td><td>场地与场次</td><td>组织者、审核员</td></tr></tbody></table><p><strong>共 12 个页面。</strong> 注意三条拆分依据：</p><p><strong>依据一：读和写分开。</strong> “活动详情”和“编辑活动”是两个页面。合并的话权限判断和状态清理都会变复杂。</p><p><strong>依据二：新增和编辑共用组件，但占两条路由。</strong> 它们字段相同，组件是一个；但用户需要能直接打开其中任意一个，所以路由是两条。</p><p><strong>依据三：同一份数据的两个入口，共用一个组件。</strong> <code>/signup</code> 和 <code>/activity/:id/signups</code> 用的是同一个列表组件，后者通过路由参数固定了活动筛选条件。</p><p><strong>为什么要有两个入口</strong>：从活动详情进报名列表时，用户的心智是“看这个活动的报名”；从侧边栏进时，心智是“看所有待审核的报名”。<strong>两种场景需求不同，但界面完全一样，所以共用一个组件。</strong></p><h2 id="四、数据字段" tabindex="-1">四、数据字段 <a class="header-anchor" href="#四、数据字段" aria-label="Permalink to &quot;四、数据字段&quot;">​</a></h2><h3 id="活动-activity" tabindex="-1">活动（Activity） <a class="header-anchor" href="#活动-activity" aria-label="Permalink to &quot;活动（Activity）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>系统生成</td><td>主键</td></tr><tr><td><code>title</code></td><td>string</td><td>是</td><td>标题，2 到 50 字</td></tr><tr><td><code>type</code></td><td>enum</td><td>是</td><td>类型：<code>LECTURE</code> 讲座 / <code>COMPETITION</code> 比赛 / <code>PERFORMANCE</code> 演出 / <code>SPORTS</code> 体育 / <code>VOLUNTEER</code> 志愿服务 / <code>OTHER</code> 其他</td></tr><tr><td><code>organizerId</code></td><td>number</td><td>系统生成</td><td>组织者 id，取自登录用户</td></tr><tr><td><code>organizerName</code></td><td>string</td><td>系统生成</td><td>组织者姓名，列表展示用</td></tr><tr><td><code>quota</code></td><td>number</td><td>是</td><td>名额上限，正整数，1 到 2000</td></tr><tr><td><code>approvedCount</code></td><td>number</td><td>系统维护</td><td>已通过审核的人数，<strong>只读</strong></td></tr><tr><td><code>pendingCount</code></td><td>number</td><td>系统维护</td><td>待审核人数，<strong>只读</strong></td></tr><tr><td><code>signupDeadline</code></td><td>string</td><td>是</td><td>报名截止时间，<code>yyyy-MM-dd HH:mm:ss</code></td></tr><tr><td><code>status</code></td><td>enum</td><td>系统维护</td><td><code>DRAFT</code> / <code>SIGNING</code> / <code>SIGNUP_CLOSED</code> / <code>FINISHED</code></td></tr><tr><td><code>offShelf</code></td><td>boolean</td><td>系统维护</td><td>下架标记，默认 <code>false</code></td></tr><tr><td><code>description</code></td><td>string</td><td>否</td><td>活动说明，最多 500 字</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>系统生成</td><td>创建时间</td></tr><tr><td><code>updatedAt</code></td><td>string</td><td>系统生成</td><td>最后更新时间</td></tr></tbody></table><p><strong>标“系统维护”和“系统生成”的字段，前端不能提交。</strong> 想改也改不了 —— 后端会忽略或报错。</p><h3 id="报名记录-signup" tabindex="-1">报名记录（Signup） <a class="header-anchor" href="#报名记录-signup" aria-label="Permalink to &quot;报名记录（Signup）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>系统生成</td><td>主键</td></tr><tr><td><code>activityId</code></td><td>number</td><td>是</td><td>关联的活动</td></tr><tr><td><code>activityTitle</code></td><td>string</td><td>系统生成</td><td>活动标题，列表展示用</td></tr><tr><td><code>studentId</code></td><td>number</td><td>是</td><td>学生 id</td></tr><tr><td><code>studentName</code></td><td>string</td><td>系统生成</td><td>学生姓名</td></tr><tr><td><code>studentNo</code></td><td>string</td><td>是</td><td>学号，10 位</td></tr><tr><td><code>studentClass</code></td><td>string</td><td>否</td><td>班级</td></tr><tr><td><code>status</code></td><td>enum</td><td>系统维护</td><td><code>PENDING</code> / <code>APPROVED</code> / <code>REJECTED</code> / <code>CANCELLED</code></td></tr><tr><td><code>remark</code></td><td>string</td><td>否</td><td>学生填写的备注，最多 200 字</td></tr><tr><td><code>rejectReason</code></td><td>string</td><td>驳回时必填</td><td>驳回理由，5 到 100 字</td></tr><tr><td><code>auditorName</code></td><td>string</td><td>系统生成</td><td>审核人姓名</td></tr><tr><td><code>auditedAt</code></td><td>string</td><td>系统生成</td><td>审核时间</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>系统生成</td><td>报名时间</td></tr></tbody></table><h3 id="场地-venue" tabindex="-1">场地（Venue） <a class="header-anchor" href="#场地-venue" aria-label="Permalink to &quot;场地（Venue）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>系统生成</td><td>主键</td></tr><tr><td><code>name</code></td><td>string</td><td>是</td><td>名称，2 到 50 字，<strong>全局唯一</strong></td></tr><tr><td><code>capacity</code></td><td>number</td><td>是</td><td>容量，正整数</td></tr><tr><td><code>location</code></td><td>string</td><td>否</td><td>位置，最多 100 字</td></tr><tr><td><code>remark</code></td><td>string</td><td>否</td><td>备注，最多 200 字</td></tr><tr><td><code>enabled</code></td><td>boolean</td><td>是</td><td>是否启用，默认 <code>true</code></td></tr></tbody></table><p><strong>用 <code>enabled</code> 停用，不用删除。</strong> 删掉场地，历史场次就显示不出场地名了。</p><h3 id="场次-session" tabindex="-1">场次（Session） <a class="header-anchor" href="#场次-session" aria-label="Permalink to &quot;场次（Session）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>系统生成</td><td>主键</td></tr><tr><td><code>activityId</code></td><td>number</td><td>是</td><td>关联的活动</td></tr><tr><td><code>activityTitle</code></td><td>string</td><td>系统生成</td><td>活动标题</td></tr><tr><td><code>venueId</code></td><td>number</td><td>是</td><td>关联的场地</td></tr><tr><td><code>venueName</code></td><td>string</td><td>系统生成</td><td>场地名称</td></tr><tr><td><code>startTime</code></td><td>string</td><td>是</td><td>开始时间</td></tr><tr><td><code>endTime</code></td><td>string</td><td>是</td><td>结束时间，必须晚于开始时间</td></tr><tr><td><code>status</code></td><td>enum</td><td>系统维护</td><td><code>SCHEDULED</code> / <code>ONGOING</code> / <code>FINISHED</code> / <code>CANCELLED</code></td></tr><tr><td><code>remark</code></td><td>string</td><td>否</td><td>备注（比如“初赛”），最多 100 字</td></tr></tbody></table><h3 id="用户-user" tabindex="-1">用户（User） <a class="header-anchor" href="#用户-user" aria-label="Permalink to &quot;用户（User）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>id</code></td><td>number</td><td>主键</td></tr><tr><td><code>username</code></td><td>string</td><td>登录账号</td></tr><tr><td><code>realName</code></td><td>string</td><td>姓名</td></tr><tr><td><code>role</code></td><td>enum</td><td><code>ORGANIZER</code> 组织者 / <code>AUDITOR</code> 审核员</td></tr><tr><td><code>department</code></td><td>string</td><td>所属部门（校学生会、社团联合会等）</td></tr></tbody></table><p><strong>角色只有两个。</strong> 不做细到按钮的权限，也不做动态角色配置。<strong>这两个角色已经足够覆盖需求，多加一层会显著增加复杂度。</strong></p><h2 id="五、界面要求" tabindex="-1">五、界面要求 <a class="header-anchor" href="#五、界面要求" aria-label="Permalink to &quot;五、界面要求&quot;">​</a></h2><p>不要求做视觉设计稿，但有几个地方要有明确的呈现方式。</p><h3 id="活动列表" tabindex="-1">活动列表 <a class="header-anchor" href="#活动列表" aria-label="Permalink to &quot;活动列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>呈现方式</th></tr></thead><tbody><tr><td>活动标题</td><td>可点击，进详情页</td></tr><tr><td>类型</td><td>纯文字</td></tr><tr><td>状态</td><td>彩色标签。草稿灰色、报名中绿色、报名截止橙色、已结束默认色；已下架另加一个灰标签</td></tr><tr><td>报名情况</td><td>显示“42 / 100”；名额已满时用红色加粗</td></tr><tr><td>报名截止</td><td>格式化的日期时间；已过期的时间用灰色</td></tr><tr><td>操作</td><td>详情、编辑、下架 / 恢复、删除；按状态和角色显隐</td></tr></tbody></table><h3 id="报名列表" tabindex="-1">报名列表 <a class="header-anchor" href="#报名列表" aria-label="Permalink to &quot;报名列表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>列</th><th>呈现方式</th></tr></thead><tbody><tr><td>学生姓名</td><td>纯文字</td></tr><tr><td>学号</td><td>等宽字体（方便核对）</td></tr><tr><td>班级</td><td>纯文字</td></tr><tr><td>活动标题</td><td>长标题用省略号，鼠标悬停显示完整</td></tr><tr><td>报名时间</td><td>格式化的日期时间</td></tr><tr><td>状态</td><td>彩色标签。待审核橙色、已通过绿色、已驳回红色、已取消灰色</td></tr><tr><td>审核人</td><td>纯文字，未审核时显示“—”</td></tr><tr><td>操作</td><td>通过、驳回（仅待审核时可用）；撤销（已通过或待审核时可用）</td></tr></tbody></table><h3 id="状态与提示文案" tabindex="-1">状态与提示文案 <a class="header-anchor" href="#状态与提示文案" aria-label="Permalink to &quot;状态与提示文案&quot;">​</a></h3><p>统一在 <code>utils/dict.js</code> 里维护。<strong>不要在页面里写死中文</strong>，否则同一个状态在不同页面的文案会不一致。</p><table tabindex="0"><thead><tr><th>场景</th><th>文案要求</th></tr></thead><tbody><tr><td>下架确认</td><td>“确定要下架‘活动标题’吗？下架后学生将无法报名，已有报名不受影响。”</td></tr><tr><td>删除确认</td><td>“确定要删除‘活动标题’吗？删除后不可恢复。”</td></tr><tr><td>名额已满</td><td>“名额已满，无法再通过新的报名。如需继续，请先调大名额或撤销已有的通过记录。”</td></tr><tr><td>时段冲突</td><td>“与‘活动标题’在 2026-04-10 15:00 到 18:00 的场次冲突，请调整时间或更换场地。”</td></tr><tr><td>无数据（活动）</td><td>“还没有活动。发布第一个活动，学生就能在手机上看到并报名了。”</td></tr><tr><td>无数据（报名）</td><td>“这个活动还没有收到报名。”</td></tr></tbody></table><p><strong>这几条文案的共同点：说清“发生了什么”并且给出“下一步怎么办”。</strong></p><p>对比一下不合格的文案：“操作失败”“名额不足”“数据为空”。<strong>它们都没有告诉用户接下来该做什么。</strong></p><h3 id="空状态与错误状态" tabindex="-1">空状态与错误状态 <a class="header-anchor" href="#空状态与错误状态" aria-label="Permalink to &quot;空状态与错误状态&quot;">​</a></h3><p>每个列表页都要区分这两种情况（见 <a href="/frontend-engineering-course/unit05/05-four-states.html">5.5 四态页面规范</a>）：</p><table tabindex="0"><thead><tr><th>状态</th><th>提示</th><th>提供的动作</th></tr></thead><tbody><tr><td>成功但无数据</td><td>说明为什么没有数据</td><td>“立即创建”或“去发布一个活动”</td></tr><tr><td>请求失败</td><td>说明是网络问题还是服务器问题</td><td>“重新加载”</td></tr></tbody></table><p><strong>这两种不能合并。</strong> 合并的后果是后端挂了的时候，用户以为是自己操作有问题。</p><h2 id="六、非功能要求" tabindex="-1">六、非功能要求 <a class="header-anchor" href="#六、非功能要求" aria-label="Permalink to &quot;六、非功能要求&quot;">​</a></h2><h3 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to &quot;性能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要求</th><th>标准</th></tr></thead><tbody><tr><td>首屏加载量</td><td>生产构建下不超过 400 KB（gzip 后）</td></tr><tr><td>首屏时间</td><td>Slow 4G 限速下 FCP 不超过 2 秒</td></tr><tr><td>列表响应</td><td>换页、查询有 loading 反馈，不出现无响应的空白期</td></tr><tr><td>大列表</td><td>每页最多 50 条，不一次性拉取全部数据</td></tr></tbody></table><p><strong>这些数字是优化的目标基线，也是 <a href="/frontend-engineering-course/unit12/02-build-optimize.html">12.2 构建优化</a>里要测的指标。</strong></p><h3 id="兼容性" tabindex="-1">兼容性 <a class="header-anchor" href="#兼容性" aria-label="Permalink to &quot;兼容性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>目标</th><th>标准</th></tr></thead><tbody><tr><td>桌面浏览器</td><td>Chrome / Edge 最近两个大版本</td></tr><tr><td>屏幕宽度</td><td>最小 1280 px 可用；1024 px 下可横向滚动，不破版</td></tr><tr><td>移动端</td><td><strong>管理端不要求适配</strong>。学生用的那一端是独立的 uni-app 工程，不共用这套样式</td></tr></tbody></table><p><strong>明确写上“不要求移动端适配”是有意义的。</strong> 不做这个声明的话，会有人问“手机上怎么是乱的”，而做适配要花掉大量时间在本来就不重要的场景上。</p><p>学生要用的手机端不在这个工程里 —— 它是一个单独的 uni-app 工程，有自己的页面、 自己的样式单位（rpx）和自己的组件库，规格见<a href="/frontend-engineering-course/project/mobile.html">用户端需求规格</a>。</p><h3 id="可用性" tabindex="-1">可用性 <a class="header-anchor" href="#可用性" aria-label="Permalink to &quot;可用性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要求</th><th>标准</th></tr></thead><tbody><tr><td>危险操作</td><td>删除、下架、驳回等操作必须二次确认</td></tr><tr><td>表单防重复</td><td>提交中按钮置为不可点</td></tr><tr><td>离开提醒</td><td>表单有未保存内容时，离开要提醒</td></tr><tr><td>错误可恢复</td><td>请求失败时给出重试入口，不要只提示一句</td></tr></tbody></table><h3 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要求</th><th>标准</th></tr></thead><tbody><tr><td>传输</td><td>必须使用 HTTPS</td></tr><tr><td>token 存储</td><td><code>localStorage</code>。<strong>要明白它的 XSS 风险</strong>，见 <a href="/frontend-engineering-course/unit12/01-integration.html">12.1</a></td></tr><tr><td>权限校验</td><td><strong>必须在后端做</strong>，前端只做界面控制</td></tr><tr><td>敏感信息</td><td>不把密钥写进 <code>VITE_</code> 环境变量（会被打包进产物）</td></tr></tbody></table><p><strong>最后一条要强调</strong>：前端代码里的所有东西，用户都能看到。<strong>前端没有秘密。</strong></p><h2 id="七、验收方式" tabindex="-1">七、验收方式 <a class="header-anchor" href="#七、验收方式" aria-label="Permalink to &quot;七、验收方式&quot;">​</a></h2><p>项目结束时按这份清单逐项验收。<strong>每一项都要在线上环境验证，不是本地。</strong></p><table tabindex="0"><thead><tr><th>编号</th><th>验收项</th><th>怎么验证</th></tr></thead><tbody><tr><td>1</td><td>用组织者账号能登录</td><td>输入账号密码，进入看板</td></tr><tr><td>2</td><td>未登录访问后台被拦</td><td>清掉本地存储，直接访问 <code>/activity</code>，跳登录页</td></tr><tr><td>3</td><td>登录后刷新不丢登录态</td><td>在活动列表页按 F5，仍在活动列表页</td></tr><tr><td>4</td><td>能创建一个活动</td><td>填写表单保存，列表里看到它</td></tr><tr><td>5</td><td>能发布活动</td><td>草稿活动点发布，状态变成报名中</td></tr><tr><td>6</td><td>能修改活动</td><td>改标题保存，列表里的标题变了</td></tr><tr><td>7</td><td>已发布的活动不能把名额改小于已通过人数</td><td>造一条有通过记录的活动，把名额改小，被拦下</td></tr><tr><td>8</td><td>能下架和恢复活动</td><td>下架后标签出现，恢复后消失</td></tr><tr><td>9</td><td>草稿之外的活动不能删除</td><td>报名中的活动，删除按钮不显示或点击被拦</td></tr><tr><td>10</td><td>能审核通过一条报名</td><td>状态变已通过，活动的报名数加一</td></tr><tr><td>11</td><td>驳回必须填理由</td><td>不填直接提交，被拦下</td></tr><tr><td>12</td><td>撤销通过会释放名额</td><td>撤销后活动的报名数减一</td></tr><tr><td>13</td><td>能新增场地</td><td>保存后出现在场地列表</td></tr><tr><td>14</td><td>场地重名被拦</td><td>用已存在的名称新增，提示重复</td></tr><tr><td>15</td><td>能给活动安排场次</td><td>选活动、场地、时段，保存成功</td></tr><tr><td>16</td><td>冲突的场次被拦</td><td>同一个场地安排重叠时段，提示冲突并说明和谁冲突</td></tr><tr><td>17</td><td><strong>边界相接不算冲突</strong></td><td>安排 14:00-17:00 和 17:00-20:00，应该成功</td></tr><tr><td>18</td><td>看板数字和列表一致</td><td>看板的活动总数等于活动列表的总数</td></tr><tr><td>19</td><td>组织者看不到别人的数据</td><td>用组织者账号，看活动列表只有自己的</td></tr><tr><td>20</td><td>界面按角色区分</td><td>组织者账号看不到“场地管理”菜单</td></tr><tr><td>21</td><td>子路由刷新不 404</td><td>在 <code>/activity</code> 页面按 F5，页面正常</td></tr><tr><td>22</td><td>手机能打开线上地址</td><td>用手机浏览器访问</td></tr></tbody></table><p><strong>第 17 项要单独强调。</strong> “边界相接不算冲突”是一条容易被忽略的规则，也是区分“做完”和“做对”的地方。</p><p><strong>第 18 项容易出问题。</strong> 看板和列表用的是两个接口，如果统计口径不一致（比如看板没按角色过滤），数字会对不上 —— 这种不一致用户一眼就能看出来，会严重影响可信度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>先写清“不做什么”</strong>，它决定了你遇到新需求时该不该动手。</li><li><strong>每个功能都要有可验证的验收标准。</strong> “实现了活动管理”不是验收标准，“能创建、能发布、能修改、能下架”才是。</li><li><strong>12 个页面</strong>，拆分依据是“读和写分开、新增编辑共用组件、多入口共用页面”。</li><li><strong><code>approvedCount</code>、<code>pendingCount</code>、<code>status</code>、<code>offShelf</code> 都是只读字段</strong>，前端不能提交。</li><li><strong>场地用 <code>enabled</code> 停用，不删除</strong>，否则历史场次会丢场地名。</li><li><strong>角色只有两个</strong>，够用就好。多加一层会显著增加复杂度。</li><li><strong>提示文案要给“下一步怎么办”</strong>，不能只说“操作失败”。</li><li><strong>无数据和失败必须分开</strong>，它们引导用户做的事完全不同。</li><li><strong>明确声明不做移动端适配</strong>，避免在不重要的场景上花时间。</li><li><strong>权限必须后端校验</strong>，前端只做界面控制。前端没有秘密。</li><li><strong>验收要在线上做，不是本地。</strong> 本地能跑不等于交付成功。</li><li><strong>“边界相接不算冲突”和“看板与列表数字一致”是最容易漏的两项。</strong></li></ul><hr><p>上一页：<a href="/frontend-engineering-course/project/">项目总览</a> · 下一页：<a href="/frontend-engineering-course/project/rules.html">业务规则与状态流转</a></p>',81)])])}const u=d(a,[["render",n]]);export{b as __pageData,u as default};
